; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared
; ------------------------------------------------------------
; Scratch space
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)
ntc_gnlo:		db 0			; ntc_getn: low byte
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)
ntc_lead:		db 0			; printint: digit seen
ntc_icnt:		db 0			; gets: chars typed
ntc_icap:		db 0			; gets: the buffer's capacity
ntc_sptr:		dw 0			; printbuf: text pointer
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done
ntc_ivar:		dw 0			; inputint / inkey: dest var
ntc_aptr:		dw 0			; atoi: text pointer
ntc_hookon:		db 0			; 1 = the Interrupt hook may run (set, and not running now)
ntc_hookset:	db 0			; 1 = an Interrupt hook is set
ntc_hookpend:	db 0			; 1 = an interrupt came, the hook runs at the next safe point
ntc_hook:		dw 0			; the hook Sub's call stub
ntc_hostix:		dw 0			; host platforms: IX kept over a firmware / BDOS call
ntc_rampt:		dw #7FC0		; the gate array's RAM setting now (B = port, C = value): the
								; Memory class keeps it, Graphics puts it back after drawing
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)
				db 40			; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:		ds 41			; inputint: typed text

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_irq ntc_xn @shared
;kw_irq  - normal mode: a safe point the compiler puts in long runs
;  of keywords without a branch, so interrupts are not held off
kw_irq:
			jp ntc_xn

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_cpeqvl ntc_cmp
kw_cpeqvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_eq

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## ntc_capfind ntc_data
; ntc_capfind - the body of a class's Capability(name) keyword.
;   HL = the name asked for (0 ended), DE = the result's address,
;   BC = the class's table: name (capitals, 0 ended), dw value, ..., db 0.
; The name is matched without regard to case. Found: the value, Z set (true).
; Not found: 0, NZ. Runs on the thread: no call, no push.
ntc_capfind:
			ld (ntc_capres), de
			ld (ntc_capname), hl
ntc_cf_entry:
			ld a, (bc)
			or a
			jr z, ntc_cf_none
			ld hl, (ntc_capname)
ntc_cf_cmp:
			ld a, (hl)
			cp 'a'
			jr c, ntc_cf_up
			cp 'z' + 1
			jr nc, ntc_cf_up
			sub 32
ntc_cf_up:
			ld e, a
			ld a, (bc)
			cp e
			jr nz, ntc_cf_skip
			or a
			jr z, ntc_cf_found
			inc hl
			inc bc
			jr ntc_cf_cmp
ntc_cf_skip:
			ld a, (bc)			; the rest of this name, its 0 and its value
			inc bc
			or a
			jr nz, ntc_cf_skip
			inc bc
			inc bc
			jr ntc_cf_entry
ntc_cf_found:
			inc bc
			ld a, (bc)
			ld e, a
			inc bc
			ld a, (bc)
			ld d, a
			ld hl, (ntc_capres)
			ld (hl), e
			inc hl
			ld (hl), d
			xor a				; Z: found
			ret
ntc_cf_none:
			ld hl, (ntc_capres)
			ld (hl), a
			inc hl
			ld (hl), a
			inc a				; NZ: not found
			ret
ntc_capres:		dw 0
ntc_capname:	dw 0

;## ntc_memcore ntc_data ntc_mem ntc_memcore2 ntc_plat_memtop @shared
; ------------------------------------------------------------
; ntc_memcore - the Memory class, the part every scheme shares. The scheme
; (Option Memory, else the platform's default) is the section ntc_mem -
; only the one chosen is in the library (@if:): CPCExpansion (16K pages
; through the #4000 window, up to 4MB) or Small (main RAM only, no paging).
; Each class method jumps to mem_go with HL = the routine: mem_go runs it
; on the real stack (call / push are fine there), interrupts on in normal
; mode (off in turbo), and stores its HL result at mem_res (mem_go4: a Long, high
; word in mem_hi; mem_go0: no store - the routine writes the result
; itself, or there is none). A routine that fails jumps to mem_err with
; HL = the status; mem_err puts back the page that was in the window
; and unwinds to mem_go.
; Far pointer = a Long: address, page (page 0 = plain memory).
; Heap: blocks from mem_hlo to mem_hhi (a D page, or Small's main RAM),
; each with a 2 byte header: length including the header (bits 0-14),
; bit 15 = in use. Free blocks are at most #4000 (joins stop there).
; The scheme supplies: mem_start (the first call), mem_sel (HL = page
; into the window), mem_chk (HL = a page number, else BadPage).
; ------------------------------------------------------------
MEM_WIN		equ #4000
MEM_BADPAGE	equ -2

mem_a1:			dw 0
mem_a2:			dw 0
mem_a3:			dw 0
mem_res:		dw 0
mem_hi:			dw 0
mem_sp:			dw 0
mem_esp:		dw 0
mem_six:		dw 0
mem_siy:		dw 0
mem_need:		dw 0
mem_max:		dw 0
mem_srca:		dw 0
mem_dsta:		dw 0
mem_srcp:		dw 0
mem_dstp:		dw 0
mem_left:		dw 0
mem_chunk:		dw 0
mem_cur:		dw 1			; the page in the window
mem_keep:		dw 1			; the page to put back
mem_hlo:		dw MEM_WIN		; the heap region mem_fit / mem_big work in
mem_hhi:		dw #8000
mem_store:		db 0
mem_init:		db 0			; 1 = the first call has been

; mem_go / mem_go4 / mem_go0 - HL = the routine (see above)
mem_go0:
			xor a
			jr mem_gostart
mem_go4:
			ld a, 4
			jr mem_gostart
mem_go:
			ld a, 2
mem_gostart:
			ld (mem_store), a
			ld (mem_sp), sp
			ld sp, (ntc_csp)
			ld (mem_six), ix
			ld (mem_siy), iy
			ld de, 0
			ld (mem_hi), de
			push hl
			call mem_start
			pop hl
			ld de, (mem_cur)
			ld (mem_keep), de
			ld a, (ntc_nmode)		; normal mode: interrupts in during the call (Ticks keep
			or a					; counting through a long Sort or Copy); turbo: off
			jr z, mem_gocall
			ei
mem_gocall:
			ld (mem_esp), sp
			call mem_jphl
mem_back:
			di
			ld ix, (mem_six)
			ld iy, (mem_siy)
			ld a, (mem_store)
			or a
			jr z, mem_gone
			ex de, hl
			ld hl, (mem_res)
			ld (hl), e
			inc hl
			ld (hl), d
			cp 4
			jr nz, mem_gone
			ld de, (mem_hi)
			inc hl
			ld (hl), e
			inc hl
			ld (hl), d
mem_gone:
			ld sp, (mem_sp)
			ret
mem_jphl:
			jp (hl)
mem_err:
			ld sp, (mem_esp)
			push hl
			ld hl, (mem_keep)
			call mem_sel
			pop hl
			ld de, 0
			ld (mem_hi), de
			jr mem_back

mem_chk_bad:
			ld hl, MEM_BADPAGE
			jp mem_err

;## ntc_memcore2 ntc_memcore @shared @far
; ntc_memcore2 - the rest of the shared part: far pointers, the heap, bytes
; and words. Runs on the real stack (through mem_go), so a keyword ROM set
; can place it in another ROM of the set (@far).

; mem_far - HL = a far pointer's address (Long: address, page): DE = the
; address, HL = the page (0 = plain memory). Page not 0: it must be a page
; this machine has and the address in the window, else mem_err BadPage.
mem_far:
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			or h
			ret z
			call mem_chk
			ld a, d
			and #C0
			cp #40
			jr nz, mem_chk_bad
			ret

; PageOf(ptr): a far pointer's page
mem_pageof:
			ld hl, (mem_a1)
			inc hl
			inc hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ret

; Address(ptr): its page into the window (page 0: nothing); the address
mem_address:
			ld hl, (mem_a1)
			call mem_far
			ld a, h
			or l
			call nz, mem_sel
			ex de, hl
			ret

; HeapStart(), HeapEnd(): the heap region (CPCExpansion: the window, a D page at a time)
mem_heapstart:
			ld hl, (mem_hlo)
			ret
mem_heapend:
			ld hl, (mem_hhi)
			ret
; ProgramStart(), ProgramEnd() (the first byte after the program and its
; arrays), Top() (the platform's top of free RAM), StackTop() (the real stack)
mem_progstart:
			ld hl, ntc_start
			ret
mem_progend:
			ld hl, ntc_free
			ret
mem_top:
			jp ntc_plat_memtop
mem_stacktop:
			ld hl, (ntc_csp)
			ret

; mem_atend - Z when HL = mem_hhi (the heap region's end). Keeps BC, DE, HL.
mem_atend:
			ld a, (mem_hhi)
			cp l
			ret nz
			ld a, (mem_hhi + 1)
			cp h
			ret
; mem_cap - HL = two joined blocks' length: NC = too long (over #4000), C = fine
mem_cap:
			ld a, h
			cp #40
			ret c
			scf
			ccf
			ret nz
			ld a, l
			cp 1					; #4000 exactly: C
			ret

; mem_fit - in the heap region (mem_hlo .. mem_hhi: a D page, or Small's main RAM): the first free block of mem_need
; bytes or more (free neighbours joined on the way), split when 4 or more
; bytes are left over, marked in use. Z: HL = its data. NZ: none.
mem_fit:
			ld hl, (mem_hlo)
mem_f_lp:
			call mem_atend
			jr z, mem_f_none
			ld e, (hl)
			inc hl
			ld d, (hl)
			dec hl
			bit 7, d
			jr z, mem_f_free
			res 7, d
mem_f_next:
			add hl, de
			jr mem_f_lp
mem_f_free:
			push hl
			add hl, de				; the block after
			call mem_atend
			jr z, mem_f_last
			ld c, (hl)
			inc hl
			ld b, (hl)
			bit 7, b
			jr nz, mem_f_last
			ld h, d					; free too: join them, up to #4000
			ld l, e
			add hl, bc
			call mem_cap
			jr nc, mem_f_last
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			dec hl
			jr mem_f_free
mem_f_last:
			pop hl
			push hl
			ex de, hl				; HL = its length, DE = the block
			ld bc, (mem_need)
			or a
			sbc hl, bc				; what is left over
			jr c, mem_f_small
			ld a, h
			or a
			jr nz, mem_f_cut
			ld a, l
			cp 4
			jr nc, mem_f_cut
			add hl, bc				; all of it
			ld b, h
			ld c, l
			pop hl
			jr mem_f_take
mem_f_cut:
			ex de, hl				; DE = left over, HL = the block
			pop hl
			push hl
			add hl, bc				; the free block after it
			ld (hl), e
			inc hl
			ld (hl), d
			pop hl
mem_f_take:
			ld (hl), c
			inc hl
			ld a, b
			or #80
			ld (hl), a
			inc hl
			xor a
			ret
mem_f_small:
			add hl, bc				; HL = its length again
			ex de, hl
			pop hl
			jr mem_f_next
mem_f_none:
			or 1					; NZ
			ret

; mem_big - in the heap region: join free neighbours, mem_max =
; the biggest free block's length if bigger
mem_big:
			ld hl, (mem_hlo)
mem_b_lp:
			call mem_atend
			ret z
			ld e, (hl)
			inc hl
			ld d, (hl)
			dec hl
			bit 7, d
			jr z, mem_b_free
			res 7, d
mem_b_next:
			add hl, de
			jr mem_b_lp
mem_b_free:
			push hl
			add hl, de
			call mem_atend
			jr z, mem_b_end
			ld c, (hl)
			inc hl
			ld b, (hl)
			bit 7, b
			jr nz, mem_b_end
			ld h, d
			ld l, e
			add hl, bc
			call mem_cap
			jr nc, mem_b_end
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			dec hl
			jr mem_b_free
mem_b_end:
			pop hl
			push hl
			ld hl, (mem_max)
			or a
			sbc hl, de
			pop hl
			jr nc, mem_b_next
			ld (mem_max), de
			jr mem_b_next

; ---- single bytes and words through far pointers (the window is put back)

; mem_at - mem_a1 = a far pointer's address: its page in, HL = the address
mem_at:
			ld hl, (mem_a1)
			call mem_far
			ld a, h
			or l
			call nz, mem_sel
			ex de, hl
			ret

mem_readbyte:
			call mem_at
			ld l, (hl)
			ld h, 0
			jr mem_putback
mem_readword:
			call mem_at
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jr mem_putback
mem_writebyte:
			call mem_at
			ld a, (mem_a2)
			ld (hl), a
			jr mem_putback
mem_writeword:
			call mem_at
			ld de, (mem_a2)
			ld (hl), e
			inc hl
			ld (hl), d
mem_putback:
			push hl
			ld hl, (mem_keep)
			call mem_sel
			pop hl
			ret

;## ntc_mem ntc_memcore ntc_plat_memtop @shared @far
; ------------------------------------------------------------
; ntc_mem (Small) - no paging: Alloc / Free over the free main RAM, from the
; program's end up to the first of: the platform's top (ntc_plat_memtop),
; 256 bytes under the real stack (when that is above the program), an
; Option Reserve range (ntc_rsvtab). Far pointers are plain addresses
; (page 0). Pages() = 0; the page methods give 0 or BadPage.
; ------------------------------------------------------------
mem_start:
			ld a, (mem_init)
			or a
			ret nz
			inc a
			ld (mem_init), a
			call ntc_plat_memtop	; HL = the platform's top
			ld (mem_hhi), hl
			ld hl, (ntc_csp)		; the real stack, when it is above the program
			ld de, ntc_free + 256
			or a
			sbc hl, de
			jr c, mem_ss_rsv
			ld hl, (ntc_csp)
			ld de, -256
			add hl, de
			call mem_lower
mem_ss_rsv:
			ld hl, ntc_rsvtab		; Option Reserve ranges above the program
mem_ss_rl:
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld a, d
			or e
			jr z, mem_ss_go
			push hl
			ld h, d
			ld l, e
			push hl
			ld de, ntc_free
			or a
			sbc hl, de
			pop hl
			call nc, mem_lower
			pop hl
			jr mem_ss_rl
mem_ss_go:
			ld hl, ntc_free
			ld (mem_hlo), hl
			ex de, hl
			ld hl, (mem_hhi)		; room for at least one small block, an even size
			or a
			sbc hl, de
			jr c, mem_ss_none
			ld bc, 8
			push hl
			sbc hl, bc
			pop hl
			jr c, mem_ss_none
			res 0, l
			add hl, de
			ld (mem_hhi), hl
mem_ss_init:						; DE = a block: free blocks of up to #4000
			ld hl, (mem_hhi)
			or a
			sbc hl, de
			ret z
			ld bc, #4000
			push hl
			or a
			sbc hl, bc
			pop hl
			jr c, mem_ss_len
			ld h, b
			ld l, c
mem_ss_len:
			ex de, hl
			ld (hl), e
			inc hl
			ld (hl), d
			dec hl
			add hl, de
			ex de, hl
			jr mem_ss_init
mem_ss_none:
			ld hl, ntc_free
			ld (mem_hhi), hl
			ret
; HL = a limit: mem_hhi = it when lower
mem_lower:
			push de
			ld de, (mem_hhi)
			push hl
			or a
			sbc hl, de
			pop hl
			jr nc, mem_lw_end
			ld (mem_hhi), hl
mem_lw_end:
			pop de
			ret

; no pages: nothing to switch, every page number is BadPage
mem_sel:
			ret
mem_chk:
			jp mem_chk_bad

mem_pages:
mem_freepages:
mem_ramsize:
mem_model:
mem_curpage:
mem_allocpage:
mem_bankcount:
mem_allocbank:
mem_bkstub:
			ld hl, 0
			ret
mem_pagetype:
mem_freepage:
mem_selpage:
mem_freebank:
mem_callbank:
			jp mem_chk_bad
mem_tableend:
			ld hl, ntc_free
			ret
mem_map:
			ld hl, (mem_res)
			ld (hl), 0
			ret

; Alloc(size): a plain address (page 0) of size bytes, 0 = no room
mem_alloc:
			ld hl, (mem_a1)
			ld a, h
			or l
			jr nz, mem_sa_size
			inc hl
mem_sa_size:
			ld de, #3FFF
			or a
			push hl
			sbc hl, de
			pop hl
			jr nc, mem_sa_fail
			inc hl
			inc hl
			ld (mem_need), hl
			call mem_fit
			ret z
mem_sa_fail:
			ld hl, 0
			ret

; Free(ptr): a block back. OK, or BadPage (not a block in use in the heap)
mem_free:
			ld hl, (mem_a1)
			call mem_far			; a page number: BadPage
			ex de, hl
			ld de, (mem_hlo)
			inc de
			inc de
			or a
			sbc hl, de
			jp c, mem_chk_bad
			add hl, de
			ld de, (mem_hhi)
			or a
			sbc hl, de
			jp nc, mem_chk_bad
			add hl, de
			dec hl
			bit 7, (hl)
			jp z, mem_chk_bad
			res 7, (hl)
			ld hl, 0
			ret

; Largest(): the biggest block Alloc could give now
mem_largest:
			ld hl, 0
			ld (mem_max), hl
			call mem_big
			ld hl, (mem_max)
			ld a, h
			or l
			ret z
			dec hl
			dec hl
			ret

;## ntc_ovlcom ntc_data ntc_mem ntc_plat_screen ntc_plat_key kw_stop @shared
; ------------------------------------------------------------
; ntc_ovlcom - what both overlay schemes share (ntc_ovl has the rest): the
; variables, the message when a class can't be loaded, a class's local
; memory (LocalAlloc / LocalFree), the members' result.
; ------------------------------------------------------------
OVL_NOPAGE	equ -12
OVL_STALE	equ -14			; a page file from another build of the program (its stamp differs)

ovl_blk:		dw 0			; the class block in use
ovl_pg:			dw 0			; where the caller's page goes
ovl_ix:			dw 0
ovl_cix:		dw 0
ovl_pix:		dw 0
ovl_new:		dw 0
ovl_res:		dw 0
ovl_p:			dw 0
ovl_ksp:		dw 0
ovl_kres:		dw 0
ovl_kcur:		dw 0
ovl_mt:			dw ntc_ovl_ld2	; fs_go returns into this
ovl_lblk:		dw 0			; LocalAlloc / LocalFree: the class block
ovl_ct:			dw 0			; ntc_ovl_enterc: the copy table's home row
ntc_ovl_lc:		db 0			; 1 = a call from code in the class's own page (its local entry): no switch
ntc_ovl_body:	dw 0			; a class in more than one page: the body of the copy to run
ovl_tdie:		db "Overlay not loaded: ", 0
ovl_tpage:		db "No RAM page free", 0
ovl_tfile:		db "The file didn't load", 0
ovl_tstale:		db "The file is from another build", 0
ovl_tkey:		db "Press a key", 0
ovl_tbra:		db " (", 0
ovl_tket:		db ")", 0
ovl_why:		dw 0

; it can't be loaded: the name and why, wait for a key (a program started
; with RUN" resets when it ends), then the program stops
ntc_ovl_die:
			ld (ovl_why), hl
			ld ix, ntc_ovl_die1
			jp ntc_plat_newline
ntc_ovl_die1:
			ld hl, ovl_tdie
			ld ix, ntc_ovl_die2
			jp ntc_ovl_puts
ntc_ovl_die2:
			ld hl, (ovl_blk)		; the page's name, then its file in brackets (a page
			ld de, 6				; named by its file: the file)
			add hl, de
ntc_ovl_dn1:
			ld a, (hl)				; past the file name to the page name
			inc hl
			or a
			jr nz, ntc_ovl_dn1
			ld a, (hl)
			or a
			jr z, ntc_ovl_dfile
			ld ix, ntc_ovl_dn2
			jp ntc_ovl_puts
ntc_ovl_dn2:
			ld hl, ovl_tbra
			ld ix, ntc_ovl_dn3
			jp ntc_ovl_puts
ntc_ovl_dn3:
			ld hl, (ovl_blk)
			ld de, 6
			add hl, de
			ld ix, ntc_ovl_dn4
			jp ntc_ovl_puts
ntc_ovl_dn4:
			ld hl, ovl_tket
			ld ix, ntc_ovl_die3
			jp ntc_ovl_puts
ntc_ovl_dfile:
			ld hl, (ovl_blk)
			ld de, 6
			add hl, de
			ld ix, ntc_ovl_die3
			jp ntc_ovl_puts
ntc_ovl_die3:
			ld ix, ntc_ovl_die3b
			jp ntc_plat_newline
ntc_ovl_die3b:
			ld hl, (ovl_why)
			ld de, -OVL_NOPAGE
			add hl, de
			ld a, h
			or l
			ld hl, ovl_tpage
			jr z, ntc_ovl_die4
			ld hl, (ovl_why)
			ld de, -OVL_STALE
			add hl, de
			ld a, h
			or l
			ld hl, ovl_tstale
			jr z, ntc_ovl_die4
			ld hl, ovl_tfile
ntc_ovl_die4:
			ld ix, ntc_ovl_die5
			jp ntc_ovl_puts
ntc_ovl_die5:
			ld ix, ntc_ovl_die6
			jp ntc_plat_newline
ntc_ovl_die6:
			ld hl, ovl_tkey
			ld ix, ntc_ovl_die7
			jp ntc_ovl_puts
ntc_ovl_die7:
			ld ix, kw_stop
			jp ntc_plat_getkey
; HL = text (0 ended): printed, then jp (ix)
ntc_ovl_puts:
			ld (ovl_pix), ix
ntc_ovl_pl:
			ld a, (hl)
			or a
			jr z, ntc_ovl_pe
			inc hl
			ld (ovl_p), hl
			ld ix, ntc_ovl_pn
			jp ntc_plat_putc
ntc_ovl_pn:
			ld hl, (ovl_p)
			jr ntc_ovl_pl
ntc_ovl_pe:
			ld ix, (ovl_pix)
			jp (ix)

; ntc_ovl_fresh - (call) HL = a class block + 2, the class just loaded at
; #4000: its page variables cleared, its local memory one free block.
ntc_ovl_fresh:
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			push de
			ld a, b
			or c
			jr z, ntc_ovl_noclr
			push bc
			ld h, d
			ld l, e
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_ovl_clr1
			inc de
			ldir
ntc_ovl_clr1:
			pop bc
ntc_ovl_noclr:
			pop hl
			add hl, bc				; its local memory: one free block (LocalAlloc)
			call ntc_ovl_lend
			or a
			sbc hl, de				; the size (even)
			ld a, h
			or a
			jr nz, ntc_ovl_lhd
			ld a, l
			cp 4
			jr c, ntc_ovl_lnone
ntc_ovl_lhd:
			ex de, hl
			ld (hl), e
			inc hl
			ld (hl), d
ntc_ovl_lnone:
			ret

; the members' end: HL = the result into ovl_kres, back on the thread
ntc_ovl_kret:
			ex de, hl
			ld hl, (ovl_kres)
			ld (hl), e
			inc hl
			ld (hl), d
			ld sp, (ovl_ksp)
			ret

ntc_ovl_kput:
			ex de, hl
			ld hl, (ovl_kres)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

; ntc_ovl_lend - HL = a class's local memory start: DE = it, HL = its end
; (start + the room to #8000, made even)
ntc_ovl_lend:
			ex de, hl
			ld hl, #8000
			or a
			sbc hl, de
			res 0, l
			add hl, de
			ret
; LocalAlloc(size) (mem_go): size bytes of the class's local memory - the
; rest of its page; only from the class's own code. An address, 0 = no room
ntc_ovl_lalloc:
			ld hl, (mem_a1)
			ld a, h
			or l
			jr nz, ntc_ovl_la1
			inc hl
ntc_ovl_la1:
			ld de, #3FFF
			or a
			push hl
			sbc hl, de
			pop hl
			jr nc, ntc_ovl_la0
			inc hl
			inc hl
			ld (mem_need), hl
			call ntc_ovl_lreg
			jr z, ntc_ovl_la0
			ld bc, (mem_hlo)		; the heap code, on this region
			push bc
			ld bc, (mem_hhi)
			push bc
			ld (mem_hlo), hl
			ld (mem_hhi), de
			call mem_fit
			jr z, ntc_ovl_la2
			ld hl, 0
ntc_ovl_la2:
			pop de
			ld (mem_hhi), de
			pop de
			ld (mem_hlo), de
			ret
ntc_ovl_la0:
			ld hl, 0
			ret

; LocalFree(address) (mem_go): a block back. OK, or BadPage
ntc_ovl_lfree:
			call ntc_ovl_lreg
			jp z, mem_chk_bad
			ld bc, (mem_a1)			; start + 2 <= address < end
			inc hl
			inc hl
			push hl
			ld h, b
			ld l, c
			pop bc
			or a
			sbc hl, bc
			jp c, mem_chk_bad
			add hl, bc
			or a
			sbc hl, de
			jp nc, mem_chk_bad
			add hl, de
			dec hl
			bit 7, (hl)
			jp z, mem_chk_bad
			res 7, (hl)
			ld hl, 0
			ret

;## ntc_ovl ntc_ovlcom ntc_mem ntc_plat_fs @shared
; ------------------------------------------------------------
; ntc_ovl (Small) - overlay classes with no RAM pages: one overlay area,
; #4000-#7FFF, holds one class at a time. A call to a class that isn't in
; it loads the class's file there (over the one that was). The call stub's
; _pg word keeps the class the caller runs in when the caller's own code is
; in the area (its thread is in #4000-#7FFF), else 0; the return stub
; (ntc_ovl_ret) loads that class again if another one took its place. In
; the class block, the page word is 1 while the class is in the area.
; ------------------------------------------------------------
OVL_BUSY	equ -13

ovl_cur:		dw 0			; the class block in the area, 0 = none

; ntc_ovl_enter - from a call stub (jp, SP = the caller's thread, IX = where
; to go on): HL = the class block, DE = the stub's word for the class to
; put back. Comes back on the real stack with the class in the area.
ntc_ovl_enter:
			ld (ovl_blk), hl
			ld (ovl_pg), de
			ld (ovl_ix), ix
			ld hl, 0
			add hl, sp
			ld sp, (ntc_csp)
			ld a, h					; the caller's thread in the area: its class
			and #C0
			cp #40
			ld hl, 0
			jr nz, ntc_ovl_en1
			ld hl, (ovl_cur)
ntc_ovl_en1:
			ex de, hl
			ld hl, (ovl_pg)
			ld (hl), e
			inc hl
			ld (hl), d
			ld hl, (ovl_blk)
ntc_ovl_engo:
			ld de, (ovl_cur)
			or a
			sbc hl, de
			jr z, ntc_ovl_en_in
			add hl, de
			ld ix, ntc_ovl_en_back
			jp ntc_ovl_core
ntc_ovl_en_back:
			ld a, h
			or l
			jp nz, ntc_ovl_die
ntc_ovl_en_in:
			ld ix, (ovl_ix)
			jp (ix)

; ntc_ovl_enterc - from a call stub of a class in more than one page (jp, SP =
; the caller's thread, IX = where to go on): HL = the procedure's copy table (db
; n, then n x dw block, body - the home copy first), DE = the stub's word for the
; caller's page. Picks the copy in the overlay area now (no load), else
; the home copy; ntc_ovl_body = its body; then on as ntc_ovl_enter. No stack used
; (SP is the caller's thread).
ntc_ovl_enterc:
			ld (ovl_pg), de
			ld (ovl_ix), ix
			ld b, (hl)
			inc hl
			ld (ovl_ct), hl
ntc_ovl_ec1:
			ld e, (hl)				; DE = a copy's block, HL = its body's word
			inc hl
			ld d, (hl)
			inc hl
			ld a, (ovl_cur)			; the one in the overlay area?
			cp e
			jr nz, ntc_ovl_ec2
			ld a, (ovl_cur + 1)
			cp d
			jr z, ntc_ovl_ec3
ntc_ovl_ec2:
			inc hl
			inc hl
			djnz ntc_ovl_ec1
			ld hl, (ovl_ct)			; none in the window: the home copy
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
ntc_ovl_ec3:
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld (ntc_ovl_body), hl
			ex de, hl
			ld de, (ovl_pg)
			ld ix, (ovl_ix)
			jp ntc_ovl_enter
; ntc_ovl_ret - from a return stub (jp, IX = where to go on): HL = the
; class its caller runs in (0: the caller isn't in the area). Comes back on
; the real stack with that class in the area again.
ntc_ovl_ret:
			ld sp, (ntc_csp)
			ld a, h
			or l
			jr z, ntc_ovl_rt0
			ld (ovl_ix), ix
			ld (ovl_blk), hl
			jr ntc_ovl_engo
ntc_ovl_rt0:
			jp (ix)

; ntc_ovl_core - (jp, IX = where to go on) HL = a class block: its file into
; the area. Comes back on the real stack with HL = 0, or a FileSystem status
; (the area is then empty).
ntc_ovl_core:
			ld (ovl_blk), hl
			ld (ovl_cix), ix
			ld sp, (ntc_csp)
			ld hl, (ovl_cur)		; the class in the area goes
			ld a, h
			or l
			jr z, ntc_ovl_c1
			xor a
			ld (hl), a
			inc hl
			ld (hl), a
			ld h, a
			ld l, a
			ld (ovl_cur), hl
ntc_ovl_c1:
			ld hl, (ovl_blk)		; FileSystem's Load: name, #4000, at most #4000
			ld de, 6
			add hl, de
			ld (fs_a1), hl
			ld hl, #4000
			ld (fs_a2), hl
			ld (fs_a3), hl
			ld hl, ovl_res
			ld (fs_res), hl
			ld sp, ovl_mt
			ld hl, fs_load
			jp fs_go
ntc_ovl_ld2:
			ld sp, (ntc_csp)
			ld hl, (ovl_res)		; the length, or a status
			bit 7, h
			jr nz, ntc_ovl_cback
			ld hl, (#4000)			; its first word: the build stamp, as the program's?
			ld de, NTC_STAMP
			or a
			sbc hl, de
			ld hl, OVL_STALE
			jr nz, ntc_ovl_cback		; (the area stays empty)
			ld hl, (ovl_blk)
			ld (ovl_cur), hl
			ld (hl), 1
			inc hl
			ld (hl), 0
			inc hl
			call ntc_ovl_fresh
			ld hl, 0
ntc_ovl_cback:
			ld ix, (ovl_cix)
			jp (ix)

; the class members (asm keywords, on the thread): HL = the class block,
; ovl_kres = the result's address. Code running in the area can't load or
; unload a class: that would overwrite it (OVL_BUSY, -13).

; Load(): the class's file into the area now (nothing if it is there). OK,
; a FileSystem status, or -13
ntc_ovl_kload:
			ld (ovl_ksp), sp
			ld (ovl_blk), hl
			ld de, (ovl_cur)
			or a
			sbc hl, de
			ld sp, (ntc_csp)
			jp z, ntc_ovl_kret		; HL = 0
			call ntc_ovl_kbusy
			jp z, ntc_ovl_kret
			ld hl, (ovl_blk)
			ld ix, ntc_ovl_kret
			jp ntc_ovl_core
; Z and HL = OVL_BUSY when the member was called from code in the area
ntc_ovl_kbusy:
			ld a, (ovl_ksp + 1)
			and #C0
			cp #40
			ld hl, OVL_BUSY
			ret

; Unload(): the area is empty (the next call loads the file again). OK, or -13
ntc_ovl_kunload:
			ld (ovl_ksp), sp
			ld sp, (ntc_csp)
			ld a, (hl)
			inc hl
			or (hl)
			jr z, ntc_ovl_kzero
			push hl
			call ntc_ovl_kbusy
			pop de
			jp z, ntc_ovl_kret
			xor a
			ld (de), a
			dec de
			ld (de), a
			ld h, a
			ld l, a
			ld (ovl_cur), hl
ntc_ovl_kzero:
			ld hl, 0
			jp ntc_ovl_kret

; Loaded(): True when it is in the area
ntc_ovl_kloaded:
			ld a, (hl)
			inc hl
			or (hl)
			ld hl, 0
			jp z, ntc_ovl_kput
			dec hl
			jp ntc_ovl_kput

; Page(): 0 (no RAM pages)
ntc_ovl_kpage:
			ld hl, 0
			jp ntc_ovl_kput

; ntc_ovl_lreg - ovl_lblk's class: it must be in the area (its own code is
; running). NZ: HL = its local memory start, DE = the end. Z: it isn't.
ntc_ovl_lreg:
			ld hl, (ovl_lblk)
			ld a, (hl)
			inc hl
			or (hl)
			ret z
			inc hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			add hl, bc
			push hl
			call ntc_ovl_lend
			ex de, hl
			pop hl
			ld a, 1
			or a
			ret

;## ntc_plat_data
ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; not used (a stream has no rows)
ntc_scols:		db 80			; columns
ntc_bdosa:		db 0			; ntc_bdos: A on return
ntc_smode:		db 2			; screen mode (Graphics on an Amstrad CPC: CP/M's console is mode 2)
ntc_cpmtop:		dw #FFFF		; the heap's top if lower than the BDOS (Graphics on CP/M Plus: GFH_AT)
				ds 256			; the program's real stack
ntc_cpmstack:

;## ntc_plat_bdos ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_bdos - C = BDOS function, DE = argument. A (also in ntc_bdosa)
; and HL come back. IX is kept. Interrupts are on during the call.
; ------------------------------------------------------------
ntc_bdos:
			ld (ntc_hostix), ix
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			call 5
			di
			ld sp, (ntc_ip)
			ld (ntc_bdosa), a
			ld ix, (ntc_hostix)
			jp (ix)

;## ntc_plat_screen ntc_plat_bdos ntc_plat_data ntc_data
; ntc_plat_putc - A = character: BDOS 6, count the column
ntc_plat_putc:
			ld e, a
			ld c, 6
			ld (ntc_pclink), ix
			ld ix, ntc_pc_back
			jp ntc_bdos
ntc_pc_back:
			ld ix, (ntc_pclink)
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			cp b
			jr c, ntc_pc_col
			xor a					; the terminal wrapped
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - CR LF
ntc_plat_newline:
			ld (ntc_pclink), ix
			ld e, 13
			ld c, 6
			ld ix, ntc_nl_lf
			jp ntc_bdos
ntc_nl_lf:
			ld e, 10
			ld c, 6
			ld ix, ntc_nl_done
			jp ntc_bdos
ntc_nl_done:
			xor a
			ld (ntc_curx), a
			ld ix, (ntc_pclink)
			jp (ix)

; ntc_plat_backspace - BS, space, BS (only on the current line)
ntc_plat_backspace:
			ld a, (ntc_curx)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_curx), a
			ld (ntc_pclink), ix
			ld e, 8
			ld c, 6
			ld ix, ntc_bs_sp
			jp ntc_bdos
ntc_bs_sp:
			ld e, ' '
			ld c, 6
			ld ix, ntc_bs_back
			jp ntc_bdos
ntc_bs_back:
			ld e, 8
			ld c, 6
			ld ix, (ntc_pclink)
			jp ntc_bdos
ntc_bs_none:
			jp (ix)

	IF NTC_TERM = 0
; ntc_plat_cls - a stream can't be cleared: a new line (unless at the start)
ntc_plat_cls:
			ld a, (ntc_curx)
			or a
			jr nz, ntc_plat_newline
			jp (ix)

; ntc_plat_locate - nothing on a stream
ntc_plat_locate:
			jp (ix)
	ELSE
; ntc_plat_cls - clear and home with the terminal's codes
ntc_plat_cls:
			xor a
			ld (ntc_curx), a
			ld hl, ntc_term_cls
			jp ntc_cpm_puts

; ntc_plat_locate - H = column, L = row, 1 based (kept on an 80 x 24 screen)
ntc_plat_locate:
			ld a, h
			or a
			jr nz, ntc_lc_x
			inc a
ntc_lc_x:
			cp 81
			jr c, ntc_lc_xok
			ld a, 80
ntc_lc_xok:
			ld h, a
			dec a
			ld (ntc_curx), a
			ld a, l
			or a
			jr nz, ntc_lc_y
			inc a
ntc_lc_y:
			cp 25
			jr c, ntc_lc_yok
			ld a, 24
ntc_lc_yok:
			ld l, a
			ld de, ntc_term_buf
		IF NTC_TERM = 1
			; VT52: ESC Y row+31 column+31
			ld a, 27
			ld (de), a
			inc de
			ld a, 'Y'
			ld (de), a
			inc de
			ld a, l
			add a, 31
			ld (de), a
			inc de
			ld a, h
			add a, 31
			ld (de), a
			inc de
		ELSE
			; ANSI: ESC [ row ; column H
			ld a, 27
			ld (de), a
			inc de
			ld a, '['
			ld (de), a
			inc de
			ld a, l
			ld b, '0' - 1
ntc_lc_r10:
			inc b
			sub 10
			jr nc, ntc_lc_r10
			add a, 10 + '0'
			ld c, a
			ld a, b
			cp '0'
			jr z, ntc_lc_r1
			ld (de), a
			inc de
ntc_lc_r1:
			ld a, c
			ld (de), a
			inc de
			ld a, ';'
			ld (de), a
			inc de
			ld a, h
			ld b, '0' - 1
ntc_lc_c10:
			inc b
			sub 10
			jr nc, ntc_lc_c10
			add a, 10 + '0'
			ld c, a
			ld a, b
			cp '0'
			jr z, ntc_lc_c1
			ld (de), a
			inc de
ntc_lc_c1:
			ld a, c
			ld (de), a
			inc de
			ld a, 'H'
			ld (de), a
			inc de
		ENDIF
			xor a
			ld (de), a
			ld hl, ntc_term_buf
			jp ntc_cpm_puts

; ntc_cpm_puts - HL = 0 terminated codes, each through BDOS 6
ntc_cpm_puts:
			ld (ntc_cplink), ix
ntc_cps_loop:
			ld a, (hl)
			or a
			jr z, ntc_cps_done
			inc hl
			ld (ntc_cpsp), hl
			ld e, a
			ld c, 6
			ld ix, ntc_cps_next
			jp ntc_bdos
ntc_cps_next:
			ld hl, (ntc_cpsp)
			jr ntc_cps_loop
ntc_cps_done:
			ld ix, (ntc_cplink)
			jp (ix)
ntc_cplink:		dw 0
ntc_cpsp:		dw 0
ntc_term_buf:	ds 10
		IF NTC_TERM = 1
ntc_term_cls:	db 27, "E", 27, "H", 0		; VT52: clear, home
		ELSE
ntc_term_cls:	db 27, "[2J", 27, "[H", 0	; ANSI: clear, home
		ENDIF
	ENDIF

; ntc_plat_mode - nothing on a terminal
ntc_plat_mode:
			jp (ix)
ntc_pclink:		dw 0

;## ntc_plat_key ntc_plat_bdos ntc_data
; ntc_plat_scankey - A = key or 0 (BDOS 6, E = #FF)
ntc_plat_scankey:
			ld e, #FF
			ld c, 6
			jp ntc_bdos

; ntc_plat_getkey - wait for a key (BDOS 6 until there is one)
ntc_plat_getkey:
			ld (ntc_gklink), ix
ntc_gk_poll:
			ld e, #FF
			ld c, 6
			ld ix, ntc_gk_back
			jp ntc_bdos
ntc_gk_back:
			or a
			jr z, ntc_gk_poll
			ld ix, (ntc_gklink)
			jp (ix)
ntc_gklink:		dw 0

;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - warm boot back to CP/M
ntc_plat_exit:
			jp 0

; ============================================================
; File system (FileSystem class) - BDOS files, FCBs, 128 byte records
; ============================================================
; The class's methods are keywords: they take their arguments
; into fs_a1 .. fs_a3, the result's address into fs_res, and
; jump to fs_go with HL = the routine. fs_go runs the routine on
; the real stack (call / push are fine there, as for BDOS), with
; interrupts on, and stores its HL result at fs_res (fs_go4: a
; Long, high word in fs_hi; fs_go0: no store - the routine writes
; the result itself). A routine that fails jumps to fs_err with
; HL = the status (negative); fs_err unwinds to fs_go.
;
; Slots: 0 is for Load / Save / Delete / Exists / Rename / Size,
; 1 and 2 are the handles Open gives. A slot is FS_SLOT bytes:
;   +0  FCB (36)    +36 mode (0 free, 1 read, 2 write, 3 update)
;   +37 position in the buffer (0-128)
;   +38 buffer state (0 not loaded, 1 loaded, 2 changed)
;   +39 record number in the buffer (2)   +42 buffer (128)
; Every record goes through random read / write (BDOS 33 / 34),
; so reading, writing and Seek all work the same way.

FS_SLOT		equ 170
FS_MODE		equ 36
FS_BPOS		equ 37
FS_BST		equ 38
FS_RECL		equ 39
FS_RECH		equ 40
FS_BUF		equ 42
FS_MAXH		equ 2

FS_NOTFOUND	equ -2
FS_FULL		equ -3
FS_BADNAME	equ -4
FS_NOHANDLE	equ -5
FS_BADHANDLE	equ -6
FS_EOF		equ -7
FS_TOOBIG	equ -8
FS_FAILED	equ -9
FS_EXISTS	equ -10
FS_BADMODE	equ -11

;## ntc_plat_fs ntc_data ntc_capfind @shared
fs_a1:			dw 0
fs_a2:			dw 0
fs_a3:			dw 0
fs_res:			dw 0
fs_hi:			dw 0
fs_sp:			dw 0
fs_esp:			dw 0
fs_six:			dw 0
fs_siy:			dw 0
fs_cnt:			dw 0
fs_rest:		dw 0
fs_ptr:			dw 0
fs_cap:			db 0
fs_store:		db 0			; 0 none, 2 Integer, 4 Long
fs_slots:		ds FS_SLOT * (FS_MAXH + 1)

; fs_go / fs_go4 / fs_go0 - HL = the routine (see above)
fs_go0:
			xor a
			jr fs_gostart
fs_go4:
			ld a, 4
			jr fs_gostart
fs_go:
			ld a, 2
fs_gostart:
			ld (fs_store), a
			ld (fs_sp), sp
			ld sp, (ntc_csp)
			ld (fs_six), ix
			ld (fs_siy), iy
			ld de, 0
			ld (fs_hi), de
			ei
			ld (fs_esp), sp
			call fs_jphl
fs_back:
			di
			ld ix, (fs_six)
			ld iy, (fs_siy)
			ld a, (fs_store)
			or a
			jr z, fs_gone
			ex de, hl
			ld hl, (fs_res)
			ld (hl), e
			inc hl
			ld (hl), d
			cp 4
			jr nz, fs_gone
			ld de, (fs_hi)
			inc hl
			ld (hl), e
			inc hl
			ld (hl), d
fs_gone:
			ld sp, (fs_sp)
			ret
fs_jphl:
			jp (hl)

; fs_err - HL = status: back to fs_go with it (a Long result gets -1 high)
fs_err:
			ld sp, (fs_esp)
			ld de, #FFFF
			ld (fs_hi), de
			jr fs_back

; fs_slotix - A = slot number: IX = the slot
fs_slotix:
			ld ix, fs_slots
			ld de, FS_SLOT
			or a
			ret z
fs_si_lp:
			add ix, de
			dec a
			jr nz, fs_si_lp
			ret

; fs_handle - HL = a handle from the program: IX = its slot (open), else fs_err
fs_handle:
			ld a, h
			or a
			jr nz, fs_badh
			ld a, l
			or a
			jr z, fs_badh
			cp FS_MAXH + 1
			jr nc, fs_badh
			call fs_slotix
			ld a, (ix + FS_MODE)
			or a
			ret nz
fs_badh:
			ld hl, FS_BADHANDLE
			jp fs_err

; fs_handlew - as fs_handle, and the file must be open for writing
fs_handlew:
			call fs_handle
			ld a, (ix + FS_MODE)
			cp 1
			ret nz
			ld hl, FS_BADMODE
			jp fs_err

; fs_clear - zero the slot's FCB, buffer state and record number
fs_clear:
			push ix
			pop hl
			ld b, FS_BUF
fs_cl_lp:
			ld (hl), 0
			inc hl
			djnz fs_cl_lp
			ret

; fs_parse - HL = name ("D:NAME.EXT", any case): the name part of the FCB at IX
; (bytes 0-11). A bad name goes to fs_err
fs_parse:
			push ix
			pop de
			xor a
			ld (de), a			; drive: the current one
			inc de
			push de
			ld b, 11
			ld a, ' '
fs_pa_sp:
			ld (de), a
			inc de
			djnz fs_pa_sp
			pop de				; DE = name field
			ld a, (hl)
			or a
			jr z, fs_pa_bad
			inc hl
			ld a, (hl)
			dec hl
			cp ':'
			jr nz, fs_pa_name
			ld a, (hl)
			call fs_upper
			sub 'A' - 1
			jr c, fs_pa_bad
			cp 17
			jr nc, fs_pa_bad
			ld (ix + 0), a
			inc hl
			inc hl
fs_pa_name:
			ld b, 8
			call fs_pa_part
			ld a, (ix + 1)
			cp ' '
			jr z, fs_pa_bad		; no name before the dot / the end
			ld a, (hl)
			or a
			ret z
			cp '.'
			jr nz, fs_pa_bad
			inc hl
			push ix
			pop de
			ld a, 9
			add a, e
			ld e, a
			jr nc, fs_pa_ext
			inc d
fs_pa_ext:
			ld b, 3
			call fs_pa_part
			ld a, (hl)
			or a
			ret z
fs_pa_bad:
			ld hl, FS_BADNAME
			jp fs_err
; one part: up to B characters from HL to DE, stops at '.' or the end
fs_pa_part:
			ld a, (hl)
			or a
			ret z
			cp '.'
			ret z
			call fs_upper
			cp '!'
			jr c, fs_pa_bad
			cp 127
			jr nc, fs_pa_bad
			push hl
			ld hl, fs_pa_badch
			ld c, a
fs_pa_chk:
			ld a, (hl)
			or a
			jr z, fs_pa_ok
			cp c
			jr z, fs_pa_bad2
			inc hl
			jr fs_pa_chk
fs_pa_bad2:
			pop hl
			jr fs_pa_bad
fs_pa_ok:
			pop hl
			ld a, b
			or a
			jr z, fs_pa_bad		; too long
			ld a, c
			ld (de), a
			inc de
			inc hl
			dec b
			jr fs_pa_part
fs_pa_badch:	db "*?:;<>=,[]|", 0

fs_upper:
			cp 'a'
			ret c
			cp 'z' + 1
			ret nc
			sub 32
			ret

; fs_bdos - C = function, DE = argument; IX / IY kept; A = the result
fs_bdos:
			push ix
			push iy
			call 5
			pop iy
			pop ix
			ret
; fs_fcb - C = function on the slot's FCB
fs_fcb:
			push ix
			pop de
			jr fs_bdos
; fs_dma - the slot's buffer is where records go
fs_dma:
			push ix
			pop hl
			ld de, FS_BUF
			add hl, de
			ex de, hl
			ld c, 26
			jr fs_bdos
; fs_bufpos - HL = the buffer at the current position
fs_bufpos:
			push ix
			pop hl
			ld de, FS_BUF
			add hl, de
			ld e, (ix + FS_BPOS)
			ld d, 0
			add hl, de
			ret
; fs_setrec - the record number into the FCB's random record field
fs_setrec:
			ld a, (ix + FS_RECL)
			ld (ix + 33), a
			ld a, (ix + FS_RECH)
			ld (ix + 34), a
			ld (ix + 35), 0
			ret
; fs_rdrec - read the record into the buffer: Z read, NZ none there
fs_rdrec:
			call fs_dma
			call fs_setrec
			ld c, 33
			call fs_fcb
			or a
			ret
; fs_wrrec - write the buffer as the record; a failure goes to fs_err
fs_wrrec:
			call fs_dma
			call fs_setrec
			ld c, 34
			call fs_fcb
			or a
			ret z
			ld hl, FS_FULL
			jp fs_err
; fs_fill - the buffer full of ^Z (CP/M's end of text)
fs_fill:
			push ix
			pop hl
			ld de, FS_BUF
			add hl, de
			ld b, 128
fs_fi_lp:
			ld (hl), 26
			inc hl
			djnz fs_fi_lp
			ret
; fs_flush - a changed buffer goes back to its record
fs_flush:
			ld a, (ix + FS_BST)
			cp 2
			ret nz
			call fs_wrrec
			ld (ix + FS_BST), 1
			ret
; fs_next - on to the next record (the buffer was used up)
fs_next:
			call fs_flush
			inc (ix + FS_RECL)
			jr nz, fs_nx_1
			inc (ix + FS_RECH)
fs_nx_1:
			ld (ix + FS_BPOS), 0
			ld (ix + FS_BST), 0
			ret
; fs_getb - A = the next byte, carry clear; carry set at the end of the file
fs_getb:
			ld a, (ix + FS_BPOS)
			cp 128
			call z, fs_next
			ld a, (ix + FS_BST)
			or a
			jr nz, fs_gb_have
			call fs_rdrec
			scf
			ret nz
			ld (ix + FS_BST), 1
fs_gb_have:
			call fs_bufpos
			ld a, (hl)
			inc (ix + FS_BPOS)
			or a
			ret
; fs_putb - A = the byte to write at the position
fs_putb:
			push af
			ld a, (ix + FS_BPOS)
			cp 128
			call z, fs_next
			ld a, (ix + FS_BST)
			or a
			jr nz, fs_pb_have
			call fs_rdrec			; keep what the record already holds
			call nz, fs_fill		; past the end: a fresh record
			ld (ix + FS_BST), 1
fs_pb_have:
			call fs_bufpos
			pop af
			ld (hl), a
			inc (ix + FS_BPOS)
			ld (ix + FS_BST), 2
			ret
; fs_close - write back what is left, close the file, free the slot
fs_close:
			ld a, (ix + FS_MODE)
			ld (ix + FS_MODE), 0
			cp 1
			jr z, fs_cs_rd
			call fs_flush
fs_cs_rd:
			ld c, 16
			call fs_fcb
			inc a
			ret nz
			ld hl, FS_FAILED
			jp fs_err

; fs_named - slot 0, its FCB set from the name at (fs_a1)
fs_named:
			xor a
			call fs_slotix
			call fs_clear
			ld hl, (fs_a1)
			jp fs_parse
; fs_openit - open the slot's file; not there goes to fs_err
fs_openit:
			ld c, 15
			call fs_fcb
			inc a
			ret nz
			ld hl, FS_NOTFOUND
			jp fs_err
; fs_makeit - a new empty file in place of any old one
fs_makeit:
			ld c, 19
			call fs_fcb			; delete (it need not be there)
			ld (ix + 12), 0
			ld (ix + 14), 0
			ld (ix + 32), 0
			ld c, 22
			call fs_fcb
			inc a
			ret nz
			ld hl, FS_FULL
			jp fs_err

; ---- the routines the methods name ------------------------------

; Load(name, addr, maxlen): the file into memory, at most maxlen bytes.
; Bytes loaded (whole records: CP/M keeps no exact length), or a status.
; More data than maxlen (beyond the last record's padding): FS_TOOBIG.
fs_load:
			call fs_named
			call fs_openit
			ld hl, (fs_a2)
			ld (fs_ptr), hl
			ld hl, (fs_a3)
			ld (fs_rest), hl
			ld hl, 0
			ld (fs_cnt), hl
fs_ld_lp:
			call fs_rdrec
			jr nz, fs_ld_end
			ld hl, (fs_rest)
			ld a, h
			or l
			jr nz, fs_ld_some
			ld hl, FS_TOOBIG
			jp fs_err
fs_ld_some:
			ld bc, 128			; BC = min(128, rest)
			ld a, h
			or a
			jr nz, fs_ld_bc
			ld a, l
			cp 128
			jr nc, fs_ld_bc
			ld c, l
fs_ld_bc:
			or a
			sbc hl, bc
			ld (fs_rest), hl
			ld hl, (fs_cnt)
			add hl, bc
			ld (fs_cnt), hl
			push bc
			push ix
			pop hl
			ld de, FS_BUF
			add hl, de
			ld de, (fs_ptr)
			ldir
			ld (fs_ptr), de
			pop bc
			ld a, c
			cp 128
			jr nz, fs_ld_end		; a part record: maxlen reached
			inc (ix + FS_RECL)
			jr nz, fs_ld_lp
			inc (ix + FS_RECH)
			jr fs_ld_lp
fs_ld_end:
			ld c, 16
			call fs_fcb
			ld hl, (fs_cnt)
			ret

; Save(name, addr, len): a new file holding len bytes (the last record padded with ^Z)
fs_save:
			call fs_named
			call fs_makeit
			ld hl, (fs_a2)
			ld (fs_ptr), hl
			ld hl, (fs_a3)
			ld (fs_rest), hl
fs_sv_lp:
			ld hl, (fs_rest)
			ld a, h
			or l
			jr z, fs_sv_end
			ld bc, 128
			ld a, h
			or a
			jr nz, fs_sv_bc
			ld a, l
			cp 128
			jr nc, fs_sv_bc
			ld c, l
fs_sv_bc:
			or a
			sbc hl, bc
			ld (fs_rest), hl
			push bc
			call fs_fill
			pop bc
			push ix
			pop hl
			ld de, FS_BUF
			add hl, de
			ex de, hl
			ld hl, (fs_ptr)
			ldir
			ld (fs_ptr), hl
			call fs_wrrec
			inc (ix + FS_RECL)
			jr nz, fs_sv_lp
			inc (ix + FS_RECH)
			jr fs_sv_lp
fs_sv_end:
			ld c, 16
			call fs_fcb
			inc a
			ld hl, 0
			ret nz
			ld hl, FS_FAILED
			ret

; Delete(name)
fs_delete:
			call fs_named
			ld c, 19
			call fs_fcb
			inc a
			ld hl, 0
			ret nz
			ld hl, FS_NOTFOUND
			ret

; Exists(name): True (-1) / False (0)
fs_exists:
			call fs_named
			ld c, 15
			call fs_fcb
			inc a
			ld hl, 0
			ret z
			dec hl
			ret

; Rename(old, new) - a file called new already there: FS_EXISTS
fs_rename:
			ld hl, (fs_a1)			; keep the old name
			ld (fs_a3), hl
			ld hl, (fs_a2)
			ld (fs_a1), hl
			call fs_named			; is new there already?
			ld c, 15
			call fs_fcb
			inc a
			ld hl, FS_EXISTS
			jp nz, fs_err
			ld hl, (fs_a3)			; the old name
			ld (fs_a1), hl
			call fs_named
			push ix
			ld de, 16
			add ix, de
			ld hl, (fs_a2)
			call fs_parse			; the new name at FCB + 16
			pop ix
			ld c, 23
			call fs_fcb
			inc a
			ld hl, 0
			ret nz
			ld hl, FS_NOTFOUND
			ret

; Size(name) As Long: bytes (whole records)
fs_size:
			call fs_named
			call fs_openit
			ld c, 35
			call fs_fcb
			ld l, (ix + 33)
			ld h, (ix + 34)
			ld e, (ix + 35)
			ld d, 0
			ld b, 7
fs_sz_lp:
			add hl, hl
			rl e
			rl d
			djnz fs_sz_lp
			ld (fs_hi), de
			ret

; Open(name, mode): a handle (1 or 2), or a status.
; mode 1 read (must be there), 2 write (a new file), 3 update (read and write; made if not there)
fs_open:
			ld a, 1
fs_op_find:
			push af
			call fs_slotix
			pop af
			ld b, a
			ld a, (ix + FS_MODE)
			or a
			jr z, fs_op_got
			ld a, b
			inc a
			cp FS_MAXH + 1
			jr c, fs_op_find
			ld hl, FS_NOHANDLE
			jp fs_err
fs_op_got:
			ld a, b
			ld (fs_cap), a			; the handle
			call fs_clear
			ld hl, (fs_a1)
			call fs_parse
			ld a, (fs_a2)
			ld hl, (fs_a2)
			ld e, a
			ld a, h
			or a
			jr nz, fs_op_bad
			ld a, e
			cp 1
			jr z, fs_op_rd
			cp 2
			jr z, fs_op_wr
			cp 3
			jr z, fs_op_up
fs_op_bad:
			ld hl, FS_BADMODE
			jp fs_err
fs_op_rd:
			call fs_openit
			jr fs_op_done
fs_op_wr:
			call fs_makeit
			jr fs_op_done
fs_op_up:
			ld c, 15
			call fs_fcb
			inc a
			jr nz, fs_op_done
			ld (ix + 12), 0
			ld (ix + 32), 0
			call fs_makeit
fs_op_done:
			ld a, (fs_a2)
			ld (ix + FS_MODE), a
			ld a, (fs_cap)
			ld l, a
			ld h, 0
			ret

; Close(h)
fs_closeh:
			ld hl, (fs_a1)
			call fs_handle
			call fs_close
			ld hl, 0
			ret

; ReadByte(h): 0-255, or FS_EOF
fs_readb:
			ld hl, (fs_a1)
			call fs_handle
			call fs_getb
			ld hl, FS_EOF
			ret c
			ld l, a
			ld h, 0
			ret

; WriteByte(h, b)
fs_writeb:
			ld hl, (fs_a1)
			call fs_handlew
			ld a, (fs_a2)
			call fs_putb
			ld hl, 0
			ret

; Read(h, addr, count): bytes read (fewer at the end of the file)
fs_read:
			ld hl, (fs_a1)
			call fs_handle
			ld hl, 0
			ld (fs_cnt), hl
fs_rd_lp:
			ld hl, (fs_cnt)
			ld de, (fs_a3)
			or a
			sbc hl, de
			jr nc, fs_rd_end
			call fs_getb
			jr c, fs_rd_end
			ld hl, (fs_a2)
			ld de, (fs_cnt)
			add hl, de
			ld (hl), a
			inc de
			ld (fs_cnt), de
			jr fs_rd_lp
fs_rd_end:
			ld hl, (fs_cnt)
			ret

; Write(h, addr, count): count, or a status
fs_write:
			ld hl, (fs_a1)
			call fs_handlew
			ld hl, 0
			ld (fs_cnt), hl
fs_wr_lp:
			ld hl, (fs_cnt)
			ld de, (fs_a3)
			or a
			sbc hl, de
			jr nc, fs_wr_end
			ld hl, (fs_a2)
			ld de, (fs_cnt)
			add hl, de
			ld a, (hl)
			inc de
			ld (fs_cnt), de
			call fs_putb
			jr fs_wr_lp
fs_wr_end:
			ld hl, (fs_cnt)
			ret

; Seek(h, pos As Long): the next read / write is at byte pos (0 = the start)
fs_seek:
			ld hl, (fs_a1)
			call fs_handle
			ld hl, (fs_a2)			; the Long's address
			ld c, (hl)				; byte 0
			inc hl
			ld e, (hl)				; byte 1
			inc hl
			ld d, (hl)				; byte 2
			inc hl
			ld a, (hl)				; byte 3
			or a
			jr nz, fs_sk_bad
			bit 7, d
			jr nz, fs_sk_bad		; beyond CP/M's 8 MB
			ex de, hl				; HL = bytes 2:1
			ld a, c
			rla						; bit 7 of byte 0
			rl l
			rl h					; HL = the record
			ld a, c
			and 127
			ld c, a					; C = position in the record
			ld a, (ix + FS_BST)
			or a
			jr z, fs_sk_new
			ld a, (ix + FS_RECL)
			cp l
			jr nz, fs_sk_new
			ld a, (ix + FS_RECH)
			cp h
			jr z, fs_sk_pos
fs_sk_new:
			push hl
			push bc
			call fs_flush
			pop bc
			pop hl
			ld (ix + FS_RECL), l
			ld (ix + FS_RECH), h
			ld (ix + FS_BST), 0
fs_sk_pos:
			ld (ix + FS_BPOS), c
			ld hl, 0
			ret
fs_sk_bad:
			ld hl, FS_FAILED
			jp fs_err

; Eof(h): True when nothing more can be read (the end, or ^Z: the end of a text)
fs_eof:
			ld hl, (fs_a1)
			call fs_handle
			ld a, (ix + FS_BPOS)
			cp 128
			call z, fs_next
			ld a, (ix + FS_BST)
			or a
			jr nz, fs_ef_have
			call fs_rdrec
			jr nz, fs_ef_yes
			ld (ix + FS_BST), 1
fs_ef_have:
			call fs_bufpos
			ld a, (hl)
			cp 26
			jr z, fs_ef_yes
			ld hl, 0
			ret
fs_ef_yes:
			ld hl, -1
			ret

; ReadLine(h) As String: up to CR LF / LF (not kept), the end or ^Z; cut at the string's size
fs_readln:
			ld hl, (fs_a1)
			call fs_handle
			ld hl, (fs_res)
			dec hl
			ld a, (hl)
			ld (fs_cap), a			; the result's capacity
			inc hl
			ld (fs_ptr), hl
			ld hl, 0
			ld (fs_cnt), hl
fs_rl_lp:
			call fs_getb
			jr c, fs_rl_end
			cp 26
			jr z, fs_rl_z
			cp 10
			jr z, fs_rl_end
			cp 13
			jr z, fs_rl_lp
			ld c, a
			ld a, (fs_cap)
			ld hl, fs_cnt
			cp (hl)
			jr z, fs_rl_lp			; full: the rest of the line is dropped
			inc (hl)
			ld hl, (fs_ptr)
			ld (hl), c
			inc hl
			ld (fs_ptr), hl
			jr fs_rl_lp
fs_rl_z:
			dec (ix + FS_BPOS)		; leave the ^Z: Eof sees it
fs_rl_end:
			ld hl, (fs_ptr)
			ld (hl), 0
			ret

; WriteLine(h, s): the text and CR LF
fs_writeln:
			ld hl, (fs_a1)
			call fs_handlew
fs_wl_lp:
			ld hl, (fs_a2)
			ld a, (hl)
			or a
			jr z, fs_wl_end
			inc hl
			ld (fs_a2), hl
			call fs_putb
			jr fs_wl_lp
fs_wl_end:
			ld a, 13
			call fs_putb
			ld a, 10
			call fs_putb
			ld hl, 0
			ret

; fs_strout - HL = text (0 ended) into the String result at (fs_res), cut at its size
fs_strout:
			ex de, hl
			ld hl, (fs_res)
			dec hl
			ld b, (hl)			; the capacity
			inc hl
			ex de, hl
fs_so_lp:
			ld a, (hl)
			or a
			jr z, fs_so_end
			ld c, a
			ld a, b
			or a
			jr z, fs_so_end
			ld a, c
			ld (de), a
			inc hl
			inc de
			dec b
			jr fs_so_lp
fs_so_end:
			xor a
			ld (de), a
			ret

; Volumes(): the drives CP/M has used so far (logged in, and the current one): "A,B"
fs_volumes:
			ld c, 24
			call fs_bdos			; HL = login vector
			push hl
			ld c, 25
			call fs_bdos			; A = current drive
			pop hl
			ld b, a
			inc b
			ld de, 1
fs_dv_bit:
			dec b
			jr z, fs_dv_or
			ex de, hl
			add hl, hl
			ex de, hl
			jr fs_dv_bit
fs_dv_or:
			ld a, l
			or e
			ld l, a
			ld a, h
			or d
			ld h, a				; HL = the drives
			ld de, fs_devtxt
			ld c, 'A'
fs_dv_lp:
			srl h
			rr l
			jr nc, fs_dv_next
			ld a, e
			cp low fs_devtxt
			jr z, fs_dv_first
			ld a, ','
			ld (de), a
			inc de
fs_dv_first:
			ld a, c
			ld (de), a
			inc de
fs_dv_next:
			inc c
			ld a, c
			cp 'Q'
			jr nz, fs_dv_lp
			xor a
			ld (de), a
			ld hl, fs_devtxt
			jp fs_strout
fs_devtxt:		ds 33

; CurrentVolume(): the current drive, "A"
fs_curvol:
			ld c, 25
			call fs_bdos
			add a, 'A'
			ld (fs_devtxt), a
			xor a
			ld (fs_devtxt + 1), a
			ld hl, fs_devtxt
			jp fs_strout

; SelectVolume(name): "B" or "B:" - the drive files without a drive letter use.
; CP/M 3 reports a drive that isn't there (NotFound); CP/M 2.2 stops with its BDOS error
fs_selvol:
			ld hl, (fs_a1)
			ld a, (hl)
			call fs_upper
			sub 'A'
			jr c, fs_sl_bad
			cp 16
			jr nc, fs_sl_bad
			ld b, a
			inc hl
			ld a, (hl)
			cp ':'
			jr nz, fs_sl_one
			inc hl
			ld a, (hl)
fs_sl_one:
			or a
			jr nz, fs_sl_bad
			push bc
			ld c, 45
			ld e, #FF			; CP/M 3: errors come back (2.2 ignores this)
			call fs_bdos
			pop bc
			ld e, b
			ld c, 14
			call fs_bdos
			inc a
			ld hl, 0
			ret nz
fs_sl_bad:
			ld hl, FS_NOTFOUND
			ret

; Devices() / CurrentDevice(): CP/M has discs only
fs_devices:
fs_curdev:
			ld hl, fs_n_disc
			jp fs_strout
fs_n_disc:		db "DISC", 0

; SelectDevice(name): "DISC" (any case) - OK; anything else NotFound
fs_select:
			ld hl, (fs_a1)
			ld de, fs_n_disc
fs_sd_lp:
			ld a, (hl)
			call fs_upper
			ld c, a
			ld a, (de)
			cp c
			jr nz, fs_sd_bad
			or a
			jr z, fs_sd_ok
			inc hl
			inc de
			jr fs_sd_lp
fs_sd_ok:
			ld hl, 0
			ret
fs_sd_bad:
			ld hl, FS_NOTFOUND
			ret

; Capability(name) - the class's table at (fs_a2); CPMVERSION (#8000 in the table) asks
; BDOS 12: #22 = CP/M 2.2, #31 = CP/M 3
fs_capab:
			ld hl, (fs_a1)
			ld de, fs_cnt
			ld bc, (fs_a2)
			call ntc_capfind
			ld hl, (fs_cnt)
			ld a, h
			cp #80
			ret nz
			ld a, l
			or a
			ret nz
			ld c, 12
			call fs_bdos
			ld l, a
			ld h, 0
			ret

;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: the BDOS (its address is at 6; the CCP below it is free, the program
; ends with a warm boot). Called on the real stack (call / ret), only by the
; Memory class.
ntc_plat_memtop:
			push de
			ld hl, (ntc_cpmtop)
			ld de, (6)
			or a
			sbc hl, de
			add hl, de
			jr c, ntc_mt1			; ntc_cpmtop lower
			ex de, hl
ntc_mt1:
			pop de
			ret


; pages (Option Page / Option Class Overlay): the RAM page each is loaded in (0 = not loaded),
; the end of its code and the size of its page variables, its file and its name
ovl_blk_level1:	dw 0, ovl_level1_end, ovl_level1_vsize
			db "OVERLAYS.001", 0, "Level1", 0	; its file, its name (for the messages)
ovl_blk_level2:	dw 0, ovl_level2_end, ovl_level2_vsize
			db "OVERLAYS.002", 0, "Level2", 0	; its file, its name (for the messages)

ntc_rsvtab:				; Option Reserve starts (the Memory class's heap stops at them), 0 ends
			dw 16384, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 16384) || (ntc_start >= 32768), "the program (or its arrays) reaches into Option Reserve #4000-#7FFF (Main.bas line 15)"
			ASSERT (ntc_free <= #4000) || (ntc_start >= #8000), "overlay classes: the program and its arrays must stay out of #4000-#7FFF (the window they run in)"

; ============================================================
; Page Level1 -> OVERLAYS.001: level1 - threads built to run at #4000
; (a RAM page, or the overlay area); their variables are in the program, but for
; Private Paged ones (after the code). Written as its own file.
; ============================================================
			OUTPUT "OVERLAYS.001"
			ORG #4000
ovl_level1_start:
			dw NTC_STAMP		; the build stamp: the loader checks it against the program's
ovl_level1__0_s:		; level1
p_level1_play:

			; Level1.cls 4: Dim i As Integer

			; Level1.cls 5: Banner "Level 1"
			dw p_banner_c, str14

			; Level1.cls 6: For i = 1 To 3
			dw kw_ltov, 1, var_level1_play_i
for4_t:

			; Level1.cls 7: Print "  room "; i
			dw kw_printstrvar, str15
			dw kw_printint, var_level1_play_i
			dw kw_printnl

			; Level1.cls 8: Next
			dw kw_next1l_n, var_level1_play_i, 3, for4_t
for4_e:

			; Level1.cls 9: Play = 100
			dw kw_ltov, 100, var_level1_play_play
			dw p_level1_play_r
p_level1_bonus:

			; Level1.cls 12: Bonus = 50
			dw kw_ltov, 50, var_level1_bonus_bonus
			dw p_level1_bonus_r
ovl_level1__0_e:
			dw 0			; (never empty)
ovl_level1_end:		; the end of its file; page variables (cleared on loading) follow
ovl_level1_vsize	equ 0		; its page variables; its local memory is the rest, to #8000
			ASSERT ovl_level1_end + ovl_level1_vsize <= #8000, "page Level1 (level1) is more than 16K (code and page variables)"
			DISPLAY "page Level1 (OVERLAYS.001):"
			DISPLAY "  level1 ", /D, ovl_level1__0_e - ovl_level1__0_s
			DISPLAY "  page variables ", /D, ovl_level1_vsize, ", free ", /D, #8000 - (ovl_level1_end + ovl_level1_vsize)
			OUTEND

; ============================================================
; Page Level2 -> OVERLAYS.002: level2 - threads built to run at #4000
; (a RAM page, or the overlay area); their variables are in the program, but for
; Private Paged ones (after the code). Written as its own file.
; ============================================================
			OUTPUT "OVERLAYS.002"
			ORG #4000
ovl_level2_start:
			dw NTC_STAMP		; the build stamp: the loader checks it against the program's
ovl_level2__0_s:		; level2
p_level2_play:

			; Level2.cls 5: Banner "Level 2"
			dw p_banner_c, str16

			; Level2.cls 6: Print "  score so far "; score; ", level 1 loaded "; Level1.Loaded()
			dw kw_printstrvar, str17
			dw kw_printint, var_level2_play_score
			dw fn_level1_loaded, var_level1_loaded_loaded
			dw kw_printstrvar, str18
			dw kw_printint, var_level1_loaded_loaded
			dw kw_printnl

			; Level2.cls 7: Print "  bonus from level 1 "; Level1.Bonus()
			dw p_level1_bonus_c
			dw kw_printstrvar, str19
			dw kw_printint, var_level1_bonus_bonus
			dw kw_printnl

			; Level2.cls 8: Play = 250
			dw kw_ltov, 250, var_level2_play_play
			dw p_level2_play_r
ovl_level2__0_e:
			dw 0			; (never empty)
ovl_level2_end:		; the end of its file; page variables (cleared on loading) follow
ovl_level2_vsize	equ 0		; its page variables; its local memory is the rest, to #8000
			ASSERT ovl_level2_end + ovl_level2_vsize <= #8000, "page Level2 (level2) is more than 16K (code and page variables)"
			DISPLAY "page Level2 (OVERLAYS.002):"
			DISPLAY "  level2 ", /D, ovl_level2__0_e - ovl_level2__0_s
			DISPLAY "  page variables ", /D, ovl_level2_vsize, ", free ", /D, #8000 - (ovl_level2_end + ovl_level2_vsize)
			OUTEND

NTC_STAMP	equ #B57B		; the build stamp: the first word of every page file
